import static org.mockito.Mockito.when;

/**
 * Unit tests for StdDelegatingSerializer#isEmpty
 */
public class StdDelegatingSerializer_isEmpty_TriageGen1Test {

    private SerializerProvider prov;
    private JsonSerializer<?> delegateSerializer;
    private TestDelegatingSerializer delegatingSerializer;

    /**
     * A concrete subclass of StdDelegatingSerializer to allow testing 
     * the protected convertValue method and to inject the delegate.
     */
    private static class TestDelegatingSerializer extends StdDelegatingSerializer {
        private final Object fixedConvertedValue;

        public TestDelegatingSerializer(JsonSerializer<?> delegate, Object fixedConvertedValue) {
            super(delegate);
            this.fixedConvertedValue = fixedConvertedValue;
        }

        @Override
        protected Object convertValue(Object value) {
            // If fixedConvertedValue is provided, return it to simulate conversion logic
            // Otherwise, return the value itself
            return fixedConvertedValue != null ? fixedConvertedValue : value;
        }
    }

    @Before
    public void setUp() {
        prov = mock(SerializerProvider.class);
        delegateSerializer = mock(JsonSerializer.class);
    }

    @Test
    public void testIsEmpty_ReturnsTrueWhenDelegateReturnsTrue() {
        // Arrange
        Object input = "some value";
        Object convertedValue = "converted";
        delegatingSerializer = new TestDelegatingSerializer(delegateSerializer, convertedValue);

        when(delegateSerializer.isEmpty(eq(prov), eq(convertedValue))).thenReturn(true);

        // Act
        boolean result = delegatingSerializer.isEmpty(prov, input);

        // Assert
        assertTrue("isEmpty should return true if delegate returns true", result);
        verify(delegateSerializer).isEmpty(prov, convertedValue);
    }

    @Test
    public void testIsEmpty_ReturnsFalseWhenDelegateReturnsFalse() {
        // Arrange
        Object input = "some value";
        Object convertedValue = "converted";
        delegatingSerializer = new TestDelegatingSerializer(delegateSerializer, convertedValue);

        when(delegateSerializer.isEmpty(eq(prov), eq(convertedValue))).thenReturn(false);

        // Act
        boolean result = delegatingSerializer.isEmpty(prov, input);

        // Assert
        assertFalse("isEmpty should return false if delegate returns false", result);
        verify(delegateSerializer).isEmpty(prov, convertedValue);
    }

    @Test
    public void testIsEmpty_WithNullValue() {
        // Arrange
        // In this case converter returns null (as per our Test implementation logic)
        delegatingSerializer = new TestDelegatingSerializer(delegateSerializer, null);

        when(delegateSerializer.isEmpty(eq(prov), eq(null))).thenReturn(true);

        // Act
        boolean result = delegatingSerializer.isEmpty(prov, null);

        // Assert
        assertTrue(result);
        verify(delegateSerializer).isEmpty(prov, null);
    }

    @Test
    public void testIsEmpty_DirectValueMapping() {
        // Arrange: Test scenario where convertValue returns the same object (no transformation)
        // We use a custom implementation of the subclass to simulate identity conversion
        delegatingSerializer = new TestDelegatingSerializer(delegateSerializer, null) {
            @Override
            protected Object convertValue(Object value) {
                return value; 
            }
        };

        Object input = new Object();
        when(delegateSerializer.isEmpty(eq(prov), eq(input))).thenReturn(false);

        // Act
        boolean result = delegatingSerializer.isEmpty(prov, input);

        // Assert
        assertFalse(result);
        verify(delegateSerializer).isEmpty(prov, input);
    }
}
